module gray_counter(
    input clk,
    input rst_n,
    output reg [4:0] count
);
    always @(posedge clk or negedge rst_n) begin
        if (~rst_n) begin
            count <= 5'b00000;
        end else begin
            count <= {count[4], count[4] ^ count[3], count[3] ^ count[2], count[2] ^ count[1], count[1] ^ count[0]};
        end
    end
endmodule

