module fsm (
        input clk,
        input reset,
        input c,
        output reg y);parameter L=0, M=1, N=2, O=3;
	reg [1:0] state, next;

	always @(posedge clk)
		if (reset)
			state <= L;
		else 
			state <= next;

	always_comb begin
		case(state)
			L: next = c ? N : M;
			M: next = c ? L : O;
			N: next = c ? O : L;
			O: next = c ? N : M;
			default: next = 'x;
		endcase
	end

	assign y = (state == M || state == O);

endmodule

