module top_module(
  input clk_in,
  input rst,
  input freq_set,
  output reg clk_out,
  output reg locked
);parameter N = 10; // multiplication factor

reg [31:0] phase_accumulator;
reg [31:0] phase_accumulator_next;
reg [31:0] phase_error;
reg [31:0] phase_error_filtered;
reg [31:0] control_signal;
reg [31:0] control_signal_filtered;
reg [31:0] freq_divider;
reg [31:0] freq_divider_next;

always @(posedge clk_in or posedge rst) begin
  if (rst) begin
    phase_accumulator <= 0;
    phase_error <= 0;
    control_signal <= 0;
    freq_divider <= 0;
  end else begin
    phase_accumulator <= phase_accumulator_next;
    phase_error <= (phase_accumulator_next >> 1) - freq_divider_next;
    control_signal <= control_signal_filtered;
    freq_divider <= freq_divider_next;
  end
end

always @(posedge clk_out or posedge rst) begin
  if (rst) begin
    phase_accumulator_next <= 0;
    freq_divider_next <= 0;
  end else begin
    phase_accumulator_next <= phase_accumulator + freq_divider;
    freq_divider_next <= freq_divider + control_signal_filtered;
  end
end

always @(posedge clk_in or posedge rst) begin
  if (rst) begin
    phase_error_filtered <= 0;
    control_signal_filtered <= 0;
  end else begin
    phase_error_filtered <= (phase_error_filtered >> 1) + (phase_error >> 1);
    control_signal_filtered <= phase_error_filtered * N;
  end
end

always @(posedge clk_in or posedge freq_set) begin
  if (freq_set) begin
    freq_divider <= 0;
    freq_divider_next <= 0;
  end
end

assign clk_out = clk_in / freq_divider;
assign locked = (phase_error_filtered < 100) && (phase_error_filtered > -100);

endmodule

