module fsm (
        input clk,
        input reset,
        input t,
        output reg y);parameter B0=0, B1=1, B2=2, B3=3;
	reg [1:0] state, next;

	always @(posedge clk)
		if (reset)
			state <= B0;
		else 
			state <= next;


	always_comb begin
		case(state)
			B0: next = t ? B1 : B3;
			B1: next = t ? B2 : B0;
			B2: next = t ? B3 : B1;
			B3: next = t ? B1 : B2;
			default: next = 'x;
		endcase
	end

	assign y = (state == B1 || state == B2);

endmodule

