module top_module(clk, load, rst_n, transmitting, shift_reg);input load;
	input transmitting;
	input clk;
	input rst_n;

	output shift_reg;

	reg [11:0] baud_cnt;
	wire [11:0] baud_cnt_val;

	assign baud_cnt_val = (load)? 12'h000: (transmitting)? baud_cnt + 1: baud_cnt;
	assign shift_reg = (baud_cnt_val == 2604) ? 1: 0;

	always @(posedge clk, negedge rst_n)
	   if(!rst_n)
	      baud_cnt <= 12'h000;
	   else if(shift_reg)
		baud_cnt <= 12'h000;
           else
	      baud_cnt <= baud_cnt_val;endmodule

