module fsm (
  input clk,
  input reset,
  input b,
  output reg t);parameter S0=0, S1=1, S2=2, S3=3;
	reg [1:0] state, next;

	always @(posedge clk) begin
		if (reset) state <= S2;
		else state <= next;
	end

	always_comb begin
		case (state)
			S0: next = b ? S2 : S1;
			S1: next = b ? S0 : S3;
			S2: next = b ? S3 : S0;
			S3: next = b ? S1 : S2;
			default: next = 'x;
		endcase
	end

	assign t = (state == S0) || (state == S2);

endmodule

