      cout_reg <= 1'b0;
    end
    else begin
      sum_reg <= a + b + cin;
      cout_reg <= (a[3] & b[3]) | (a[3] & cin) | (b[3] & cin);
    end
  end

  assign sum = sum_reg;
  assign cout = cout_reg;

endmodule

