        equal_delay <= 1'b1;
    end else begin
        equal_delay <= 1'b0;
    end
end

always @(posedge clk) begin
    if (reg_input1_delay > reg_input2_delay) begin
        greater_than_delay <= 1'b1;
    end else begin
        greater_than_delay <= 1'b0;
    end
end

endmodule

