module state_logic (
        input clk,
        input reset,
        input h,
        output reg z);parameter P=0, Q=1, R=2, S=3;
	reg [1:0] state, next;

	always @(posedge clk)
		if (reset)
			state <= P;
		else 
			state <= next;

	always_comb begin
		case(state)
			P: next = h ? R : Q;
			Q: next = h ? P : S;
			R: next = h ? S : P;
			S: next = h ? R : Q;
			default: next = 'x;
		endcase
	end

	assign z = (state == P || state == R);

endmodule

