	begin
	  temp = Signal ;
	  if ( ALUOp == 2'b00 ) temp = ADD;
	  else if ( ALUOp == 2'b01 ) temp = SUB;
	end

	assign SignaltoALU = temp ; 
	assign SignaltoSHT = temp ; 
	assign SignaltoMULT = temp ; 
	assign SignaltoMUX = temp ; 



endmodule

