description:
Design a SPI (Serial Peripheral Interface) slave module that receives an 8-bit data stream transmitted over the MOSI (Master Out Slave In) line. The module uses a finite state machine to transition through states corresponding to each bit being received, starting from an IDLE state when the slave select (ssel) signal is asserted low. Upon receiving a complete 8-bit sequence, the module sets a status indicating data has been received, while the MISO (Master In Slave Out) output is kept high unless reset. This design enables communication in embedded systems where data is exchanged serially between a master and a slave device.
module top_module(
  input clk, rst_n, ssel, sck, mosi,
  output reg miso, recived_status
);

code:
module top_module(
  input clk, rst_n, ssel, sck, mosi,
  output reg miso, recived_status
);reg [7:0] data_in; // register to store incoming data
reg [2:0] state; // state machine to keep track of received bits
parameter IDLE = 3'b000, BIT0 = 3'b001, BIT1 = 3'b010, BIT2 = 3'b011,
          BIT3 = 3'b100, BIT4 = 3'b101, BIT5 = 3'b110, BIT6 = 3'b111;

always @(posedge clk) begin
  if(!rst_n) begin
    miso <= 1'b1;
    state <= IDLE;
    data_in <= 8'b0;
    recived_status <= 1'b0;
  end
  else begin
    case(state)
      IDLE:
        if(!ssel) begin
          state <= BIT0;
        end
      BIT0:
        begin
          data_in[0] <= mosi;
          state <= BIT1;
        end
      BIT1:
        begin
          data_in[1] <= mosi;
          state <= BIT2;
        end
      BIT2:
        begin
          data_in[2] <= mosi;
          state <= BIT3;
        end
      BIT3:
        begin
          data_in[3] <= mosi;
          state <= BIT4;
        end
      BIT4:
        begin
          data_in[4] <= mosi;
          state <= BIT5;
        end
      BIT5:
        begin
          data_in[5] <= mosi;
          state <= BIT6;
        end
      BIT6:
        begin
          data_in[6] <= mosi;
          state <= IDLE;
          recived_status <= 1'b1;
        end
    endcase
  end
end

endmodule

