module sequence_detector (
    input clk,
    input in,
    input reset,
    output detected);parameter S0=0, S1=1, S01=2, S011=3, S0110=4;
    reg [2:0] state;
    reg [2:0] next;

    always_comb begin
        case (state)
            S0: next = in ? S0 : S1;
            S1: next = in ? S01 : S0;
            S01: next = in ? S011 : S0;
            S011: next = in ? S0 : S0110;
            S0110: next = in ? S0 : S1;
        endcase
    end

    always @(posedge clk) begin
        if (reset) state <= S0;
        else state <= next;
    end

    assign detected = (state == S0110);

endmodule

