Implement the Verilog module based on the following description.
Module Q implements the boolean function z = x & y | ~x.

// Module R can be described by the following simulation waveform: 

If x = 1, y = 1, then z = 0.
If x = 0, y = 1, then z = 1.
If x = 0, y = 0, then z = 1.
If x = 1, y = 0, then z = 0.

// Now consider a top-level that uses two Q submodules and two R submodules. The first input of all four submodules is connect to input 'x', and the second input of all four submodules is connected to 'y'. The output of the first Q submodule is connected to a two-input OR, along with the output of the first R submodule. The second pair of Q and R submodules is similarly connected to an AND gate. The output of the OR and the AND is connected to an XOR, whose output is 'z'.

// Implement this circuit in Verilog.

module top_module(
	input x,
	input y,
	output z);

code:
module Q(
    input x,
    input y,
    output z
);
    assign z = x & y | ~x;
endmodule

module R(
    input x,
    input y,
    output z
);
    assign z = x & ~y;
endmodule

module top_module(
    input x,
    input y,
    output z
);
    wire q1_out, q2_out, r1_out, r2_out;
    wire or_out, and_out;

    Q q1(.x(x), .y(y), .z(q1_out));
    Q q2(.x(x), .y(y), .z(q2_out));
    R r1(.x(x), .y(y), .z(r1_out));
    R r2(.x(x), .y(y), .z(r2_out));

    assign or_out = q1_out | r1_out;
    assign and_out = q2_out & r2_out;

    assign z = or_out ^ and_out;
endmodule

