module johnson_counter
    (
        input rst_n,
        input clk,
        output reg [7:0] q
    );

    always @(posedge clk or negedge rst_n) 
    begin
        if (!rst_n)
            q <= 8'd0;
        else
            q <= {~q[7], q[7:1]};
    end

endmodule

