Design a clock divider circuit that generates a derived clock output, clk_out1, at a frequency reduced by a factor determined by the 16-bit input freq_div from the incoming clock signal, clk_in1. The output clock toggles state based on the count of clock cycles defined by freq_div, effectively producing a lower frequency clock signal that can be used for various timing applications in digital circuitry.
module top_module(
  input clk_in1,
  input [15:0] freq_div,
  output reg clk_out1
);

code:
module top_module(
  input clk_in1,
  input [15:0] freq_div,
  output reg clk_out1
);reg [15:0] counter = 0;
  reg [15:0] div = freq_div - 1;

  always @(posedge clk_in1) begin
    counter <= counter + 1;
    if (counter >= div) begin
      counter <= 0;
      clk_out1 <= ~clk_out1;
    end
  end

endmodule

