module light_switch (
        input clk,
        input areset,
        input switch_flipped,
        output reg light_on);parameter Off=1'b0, On=1'b1;
	reg state;
	always @(posedge clk, posedge areset) begin
		if (areset)
			state <= Off;
		else begin
			case (state)
				Off: state <= switch_flipped ? On : Off;
				On: state <= switch_flipped ? Off : On;
			endcase
		end
	end

	assign light_on = (state == On);

endmodule

