module vending_machine (
	input clk,
	input resetn,
	input [1:0] coin,
	output dispense);

	parameter IDLE=0, FIVE=1, TEN=2, FIFTEEN=3;
	reg [1:0] state, next_state;
	reg [3:0] total;

	always @(posedge clk) begin
		if (~resetn) state <= IDLE;
		else state <= next_state;
	end

	always @(posedge clk) begin
		if (coin == 2'b01) total <= total + 4'd5;
		else if (coin == 2'b10) total <= total + 4'd10;
		else total <= total;

		if (state == FIFTEEN) total <= 0;
	end

	always_comb begin
		case (state)
			IDLE: next_state = (total >= 4'd15) ? FIFTEEN : IDLE;
			FIVE: next_state = (total >= 4'd15) ? FIFTEEN : FIVE;
			TEN: next_state = (total >= 4'd15) ? FIFTEEN : TEN;
			FIFTEEN: next_state = IDLE;
			default: next_state = IDLE;
		endcase
	end

	assign dispense = (state == FIFTEEN);
endmodule

