// Pipeline stage 1
always @(*) begin
    stage1_out = ~binary;
end

// Pipeline stage 2
always @(*) begin
    stage2_out = ~stage1_out;
end

// Output stage
always @(posedge clk) begin
    ones_comp <= stage2_out;
end

endmodule

